using System.Text.Json;
using EqlTracker.Core;

internal static class TrackerPolishTests
{
    internal static void Register(Action<string,Action> test)
    {
        void Check(bool ok){if(!ok)throw new Exception("Tracker polish regression");}
        test("Legacy combat selections migrate to an unfiltered independent tracker",()=>{var p=new CharacterProfile { Meter=new(){Actor="Player",Scope="History",EncounterId="pinned",SessionId="old",Target="mob",Ability="spell",Kind="Spell",CriticalOnly=true,From=DateTime.Today,ClassCombinations=["MAG/BRD/SHD"],Sort="Average"} };string before=JsonSerializer.Serialize(p.Meter);TrackerPresentation.Migrate(p);Check(JsonSerializer.Serialize(p.Meter)==before&&p.OverlayMeter!.Scope=="Fight"&&p.OverlayMeter.Actor=="Player"&&p.OverlayMeter.Sort=="Average"&&p.OverlayMeter.FilterCount==0&&p.OverlayMeter.EncounterId==""&&p.OverlayMeter.SessionId=="");});
        test("Independent selections survive restart without resetting saved filters",()=>{var p=new CharacterProfile();TrackerPresentation.Migrate(p);p.OverlayMeter!.Ability="Slash";p.OverlayMeter.ClassCombinations.Add("Unknown");p.Meter.Ability="Fire";var copy=JsonSerializer.Deserialize<CharacterProfile>(JsonSerializer.Serialize(p))!;TrackerPresentation.Migrate(copy);Check(copy.OverlayMeter!.Ability=="Slash"&&copy.Meter.Ability=="Fire"&&copy.OverlayMeter.ClassCombinations.Single()=="Unknown");copy.OverlayMeter.ClassCombinations.Clear();Check(p.OverlayMeter.ClassCombinations.Count==1);});
        test("Clear tracker filters retains actor scope sorting and session",()=>{var p=new DpsSelection{Actor="Combined",Scope="Session",SessionId="saved",Sort="Hits",Target="mob",Ability="spell",Kind="Spell",CriticalOnly=true,From=DateTime.Today,Until=DateTime.Today.AddDays(1),ClassCombinations=["Unknown"]};Check(p.FilterCount==7);p.ClearFilters();Check(p.FilterCount==0&&p.Actor=="Combined"&&p.Scope=="Session"&&p.SessionId=="saved"&&p.Sort=="Hits");});
        test("Selection copies isolate class collections and individual filters",()=>{var p=new DpsSelection{ClassCombinations=["Mixed"],Ability="A"};var copy=p.Copy();copy.ClassCombinations.Clear();copy.Ability="B";Check(p.ClassCombinations.Count==1&&p.Ability=="A");});
        test("Roman-numbered focus spell identities stay distinct from logged ranks",()=>{Check(EffectReferences.Key("Focus: Summoning Haste I")!=EffectReferences.Key("Focus: Summoning Haste II")&&SpellReference.BaseName("Fire Bolt III")=="Fire Bolt");});
        test("Fourteen stable race styles include exact Cut Stone default label",()=>{Check(TrackerPresentation.Tabs.Length==14&&TrackerPresentation.Tabs.Select(x=>x.Id).Distinct().Count()==14&&new CharacterProfile().TrackerTabs==TrackerTabStyle.Dwarf&&TrackerPresentation.Tabs.Single(x=>x.Id==TrackerTabStyle.Dwarf).Name=="Cut Stone - Dwarf");});
        test("Helper text follows resolved theme families and retains custom legacy values",()=>{var p=new CharacterProfile{SecondaryText="Parchment Ivory"};TrackerPresentation.Migrate(p);Check(p.SecondaryText=="Parchment Ivory"&&TrackerPresentation.Secondary(p,"Rune4K_Frost_Clear")=="Candlelight Cream"&&TrackerPresentation.Secondary(p,"Rune4K_Vellum_Clear")=="Warm Gold");p.SecondaryTextByTheme["Frost"]="Bright Frost";TrackerPresentation.Migrate(p);Check(TrackerPresentation.Secondary(p,"Midnight")=="Bright Frost"&&TrackerPresentation.Secondary(p,"Warm Amber")=="Warm Gold");});
        test("Independent damage views keep identical calculation rules",()=>{var at=new DateTime(2026,10,19,12,0,0);var fight=new Encounter{Id="f",Start=at,End=at.AddSeconds(10),Finished=true,Events=[new(){Time=at,Owner="Player",Ability="Slash",Kind="Melee",Target="A",Damage=100,Outcome="Hit"},new(){Time=at.AddSeconds(10),Owner="Pet",Ability="Fire",Kind="Spell",Target="B",Damage=200,Outcome="Hit"}]};var lab=new DpsSelection{Actor="Combined",Ability="Fire"};var overlay=new DpsSelection{Actor="Combined"};var a=DpsViews.Build([fight],null,at,lab);var b=DpsViews.Build([fight],null,at,overlay);Check(a.Damage==200&&b.Damage==300&&a.Seconds==b.Seconds);lab.Target="absent";Check(DpsViews.Build([fight],null,at,lab).Damage==0&&DpsViews.Build([fight],null,at,overlay).Damage==300);});
        test("Balanced spell fields preserve nested templates and later numeric fields",()=>{var text="{{Spellpagesmart|description=Test|slots={{SpellSlotRow | 1 | Decrease Hitpoints by 50 per tick }}|duration=4 ticks|target_type=Single|resist=Magic (-100)}}";var r=SpellReference.Parse("Test",text,3)!;Check(r.ParserVersion==2&&r.Effects=="Decrease Hitpoints by 50 per tick"&&r.Fields["duration"]=="4 ticks"&&r.Details.Contains("Magic (-100)"));});
        test("Sourced Swarming Pain numbers remain base reference and separate from activation",()=>{var source=new ItemDefinition{EffectActivationLevel=50};var r=SpellReference.Parse("Swarming Pain","{{Spellpage|description=50 damage every 6 seconds|slots={{SpellSlotRow | 4 | Decrease Hitpoints by 50 per tick }}|duration=1 ticks @L1 to 4 ticks @L8|target_type=Single|resist=Magic (-100)}}",104727)!;var v=EffectReferences.Build("Proc: Swarming Pain (Combat)",source,r);Check(v.Status==EffectReferenceStatus.Available&&v.Lines.Any(l=>l.Label=="Tick interval"&&l.Value.StartsWith("6"))&&v.Lines.Any(l=>l.Label=="Base reference maximum"&&l.Value.Contains("200"))&&v.Lines.Any(l=>l.Label=="Item activation"&&l.Value.StartsWith("Level 50")));});
        test("Conflicting metadata and missing metadata never become numeric zero",()=>{var r=SpellReference.Parse("Spirit Tap","{{Spellpage|description=siphoning 210 hit points|slots={{SpellSlotRow | 1 | Decrease Hitpoints by 132 to 150 }}|duration=Instant}}",1)!;Check(EffectReferences.Build("Spirit Tap",new(),r).Status==EffectReferenceStatus.Conflicting);var missing=EffectReferences.Build("Unknown",new(),null,true);Check(missing.Status==EffectReferenceStatus.Unavailable&&missing.Lines.Count==0&&missing.Limitation.Contains("unknown"));});
        test("Effect reference names preserve item identifiers and strip only socket annotations",()=>{Check(EffectReferences.Name("Proc: Swarming Pain (Combat, Casting Time: Instant)")=="Swarming Pain"&&EffectReferences.Name("Click: Siphon Strength (Must Equip)")=="Siphon Strength");var p=new CharacterProfile();p.ActiveLoadout.Equipment.Add(new(){Name="Example +17",Augments=[new(){Name="Old alias",EffectIdentity="legacy-id"}]});TrackerPresentation.Migrate(p);Check(p.ActiveLoadout.Equipment.Single().Rank==17&&p.ActiveLoadout.Equipment.Single().Augments.Single().EffectIdentity=="legacy-id");});
    }
}
